                        if 0<=x<H and 0<=y<W and g[x,y]!=0 and not vis[x,y]:
                            vis[x,y]=True;q.append((x,y))
                rs=[r for r,_ in cells];cs=[c for _,c in cells]
                out.append(((min(rs),min(cs)),(max(rs),max(cs))))
    return out
def solve(gin):
    g=np.array(gin);H,W=g.shape
    bl=comps(g)
    cnt=Counter(int(v) for v in g.flat)
    bg=cnt.most_common(1)[0][0]
    # interior colors of blocks (3x3 rings -> center; general: interior cells)
    info={}
    for (a,b),(c,d) in bl:
        inner=set(int(g[r,c2]) for r in range(a+1,c) for c2 in range(b+1,d+1))
        info[(a+1,b+1)]=inner
    icnt=Counter(info.values())
    mod=icnt.most_common(1)[0][0]
    rareC=[k for k,v in info.items() if v!=mod]
    chg=[[k]*0 for k in range(0)]  # placeholder
    out=g.copy()
    for axis in (0,1):
        keys=sorted(rareC,key=lambda k:(k[0],k[1]) if axis==0 else (k[1],k[0]))
        # group by other coordinate
        from collections import defaultdict
        grp=defaultdict(list)
        for k in rareC: grp[k[axis]].append(k)
        for coord,ks in grp.items():
            ks=sorted(ks)
            for p,q_ in zip(ks,ks[1:]):
                if axis==0:
                    rng=range(p[0]+1,q_[0])
                    if any(not(0<=r<H) for r in rng): continue
                    cells=[(r,p[1]) for r in rng if g[r,p[1]]==bg]
                    col=list(info[p])[0] if len(info[p])==1 else None
                    col=list(info[q_])[0] if len(info[q_])==1 else None
                else:
                    rng=range(p[1]+1,q_[1])
                    cells=[(p[0],c) for c in rng if g[p[0],c]==bg]
                    col=list(info[p])[0] if len(info[p])==1 else None
                    col=list(info[q_])[0] if len(info[q_])==1 else None
