def comps(g):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=0 and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            yy,xx=y+dy,x+dx
                            if 0<=yy<R and 0<=xx<C and g[yy][xx]!=0 and not seen[yy][xx]:
                                seen[yy][xx]=True; st.append((yy,xx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                out.append((min(ys),min(xs),max(ys),max(xs)))
    return out
